/**
 * The consumer template tree is generated by scripts/sync-agents.mjs and
 * committed, and `guardrails init` (piece 4) writes it into a target repo. A
 * file silently dropped from it would produce a consumer whose fixer agents or
 * hooks never got written — which looks like a working install right up until
 * the loop does not fire. These assertions are the contract.
 */
import { spawn, spawnSync } from 'node:child_process';
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import process from 'node:process';

import { describe, expect, it } from 'vitest';

import { LOCK_TIMEOUT_MARKER, NOT_INSTALLED_MARKER } from '../src/ship.js';

const templates = path.join(import.meta.dirname, '..', 'templates');

const EXPECTED_FILES = [
  'claude/agents/guardrail-fixer.md',
  'claude/agents/guardrail-fixer-thorough.md',
  'claude/settings.hooks.json',
  'codex/agents/guardrail-fixer.toml',
  'codex/agents/guardrail-fixer-thorough.toml',
  'codex/hooks.json',
  'copilot/agents/guardrail-fixer.agent.md',
  'copilot/agents/guardrail-fixer-thorough.agent.md',
  'copilot/hooks/guardrails.json',
  'githooks/pre-commit',
  'githooks/pre-push',
  'workflows/guardrails.yml',
] as const;

describe('consumer templates', () => {
  it.each(EXPECTED_FILES)('ships %s', (relative) => {
    expect(existsSync(path.join(templates, relative))).toBe(true);
  });

  it('grants every fixer surface a way to SEARCH, under its own tool name', () => {
    // The two surfaces name the same capability differently, and a grant
    // written for one silently does not apply to the other: Claude Code takes
    // `Grep`/`Glob`, while Copilot takes `search` (with those two as
    // documented aliases). Two fixer runs made no edit at all for want of
    // this, so a surface shipping without it is a regression worth failing on.
    for (const agent of ['guardrail-fixer', 'guardrail-fixer-thorough']) {
      const claude = readFileSync(
        path.join(templates, 'claude', 'agents', `${agent}.md`),
        'utf8',
      );
      expect(claude).toContain('tools: Read, Grep, Glob, Edit, Write');

      const copilot = readFileSync(
        path.join(templates, 'copilot', 'agents', `${agent}.agent.md`),
        'utf8',
      );
      // Copilot's CANONICAL identifiers, not the names its runtime reports.
      // Unrecognised entries are silently ignored there, so a list written in
      // the wrong namespace grants nothing and says nothing — which is how
      // this channel shipped with a fixer that could not read its own
      // manifest. Pinned exactly, so a well-meant `view` cannot creep back.
      expect(copilot).toContain('tools: [read, edit, search]');
    }
  });

  it('withholds execution, fan-out and the network from the Copilot fixer', () => {
    // The capability boundary, in Copilot's vocabulary. `execute` is the one
    // that matters most: the diff-auditor and re-verify are trusted because a
    // fixer can only propose text, and a fixer that can run commands can run a
    // weakened suite and report success.
    for (const agent of ['guardrail-fixer', 'guardrail-fixer-thorough']) {
      const copilot = readFileSync(
        path.join(templates, 'copilot', 'agents', `${agent}.agent.md`),
        'utf8',
      );
      const tools = /^tools: \[(.*)]$/m.exec(copilot)?.[1] ?? '';
      for (const withheld of [
        'execute',
        'shell',
        'Bash',
        'powershell',
        'agent',
        'web',
        'WebFetch',
        'todo',
      ]) {
        expect(tools.split(', ')).not.toContain(withheld);
      }
      expect(copilot).toContain('agents: []');
    }
  });

  it('carries all five Claude hook events', () => {
    const raw: unknown = JSON.parse(
      readFileSync(
        path.join(templates, 'claude', 'settings.hooks.json'),
        'utf8',
      ),
    );
    expect(raw).toHaveProperty('hooks');
    const { hooks } = raw as { hooks: Record<string, unknown> };
    expect(Object.keys(hooks).toSorted((a, b) => a.localeCompare(b))).toEqual([
      'PostToolUse',
      'PreToolUse',
      'SessionEnd',
      'SessionStart',
      'Stop',
    ]);
  });

  it('ships all five Codex lifecycle hooks with the Codex dialect', () => {
    const hooks = readFileSync(
      path.join(templates, 'codex', 'hooks.json'),
      'utf8',
    );
    for (const event of [
      'SessionStart',
      'SessionEnd',
      'PreToolUse',
      'PostToolUse',
      'Stop',
    ]) {
      expect(hooks).toContain(`"${event}"`);
    }
    expect(hooks).toContain('--dialect=codex');
    expect(hooks).toContain('apply_patch');
  });

  it('ships valid-looking Codex custom agent definitions', () => {
    const agents = [
      ['guardrail-fixer.toml', 'gpt-5.6-luna', 'low'],
      ['guardrail-fixer-thorough.toml', 'gpt-5.6-terra', 'high'],
    ] as const;
    for (const [agent, model, reasoning] of agents) {
      const content = readFileSync(
        path.join(templates, 'codex', 'agents', agent),
        'utf8',
      );
      expect(content).toContain('name = "guardrail-fixer');
      expect(content).toContain(`model = "${model}"`);
      expect(content).toContain(`model_reasoning_effort = "${reasoning}"`);
      expect(content).toContain('sandbox_mode = "workspace-write"');
      expect(content).toContain("developer_instructions = '''");
    }
  });

  it('ships the self-filtering Claude scope-lock hook', () => {
    const hooks = readFileSync(
      path.join(templates, 'claude', 'settings.hooks.json'),
      'utf8',
    );
    expect(hooks).toContain('"matcher": "Read|Grep|Glob|Edit|Write"');
    expect(hooks).toContain('scope-check');
  });

  it('resolves guardrails-core through package resolution, never a repo-local path', () => {
    // A template that pointed at this repo's own layout would break in every
    // consumer. The hook commands must resolve the guardrails-core package
    // through Node's module resolution, by name via `-e "import(...)"`, never
    // this repository's own source directory.
    const hooks = readFileSync(
      path.join(templates, 'claude', 'settings.hooks.json'),
      'utf8',
    );
    expect(hooks).toContain("import('guardrails-core/cli')");
    expect(hooks).not.toContain('guardrails-core/src');
  });

  it('ships a pre-commit hook that runs the commit gate', () => {
    const hook = readFileSync(
      path.join(templates, 'githooks', 'pre-commit'),
      'utf8',
    );
    expect(hook).toContain('gate --mode=commit');
  });

  it('ships a pre-commit hook with no prose about THIS repo in it', () => {
    // The hook is copied verbatim into every scaffolded repo, so a sentence
    // true only here ("this repo uses Husky instead, see .husky/pre-commit")
    // lands as a false instruction there: a consumer has no `.husky/`, and
    // following the pointer leads nowhere.
    const hook = readFileSync(
      path.join(templates, 'githooks', 'pre-commit'),
      'utf8',
    );
    expect(hook).not.toContain('.husky');
    expect(hook).not.toContain('This repo');
  });

  it('ships a pre-push hook that runs the branch-scoped gate', () => {
    // The commit rung scopes to staged files, so this is what re-checks the
    // whole branch before anything leaves the machine.
    const hook = readFileSync(
      path.join(templates, 'githooks', 'pre-push'),
      'utf8',
    );
    expect(hook).toContain('gate --mode=push');
  });

  it('ships a pre-push hook with no prose about THIS repo in it', () => {
    const hook = readFileSync(
      path.join(templates, 'githooks', 'pre-push'),
      'utf8',
    );
    expect(hook).not.toContain('.husky');
    expect(hook).not.toContain('This repo');
  });

  it.each(['pre-commit', 'pre-push'])(
    'ships a %s hook that says so when guardrails-core is not installed',
    (name) => {
      // A fresh worktree has no node_modules. The hook used to report that as
      // "commit blocked — resolve violations", which sent agents hunting for
      // violations that did not exist. It must still block (exit 1): a gate
      // that cannot run is not a gate that passed.
      const checkout = mkdtempSync(path.join(tmpdir(), 'guardrails-githook-'));
      try {
        const result = spawnSync(
          'sh',
          [path.join(templates, 'githooks', name)],
          {
            cwd: checkout,
            encoding: 'utf8',
          },
        );
        expect(result.status).toBe(1);
        expect(result.stderr).toContain('not installed');
        expect(result.stderr).toContain('npm ci');
        expect(result.stderr).not.toContain('resolve violations');
      } finally {
        rmSync(checkout, { recursive: true, force: true });
      }
    },
  );

  it('ships a CI workflow that runs the ci gate plus sanctions-check', () => {
    // `--mode=ci`, not `--mode=commit`: the commit rung scopes to STAGED
    // files, and nothing is staged in a CI checkout, so the old spelling would
    // check an empty set and report clean.
    const workflow = readFileSync(
      path.join(templates, 'workflows', 'guardrails.yml'),
      'utf8',
    );
    expect(workflow).toContain('gate --mode=ci');
    expect(workflow).not.toContain('gate --mode=commit');
    expect(workflow).toContain('sanctions-check');
  });

  it('invokes the CLI by local path, never through npx', () => {
    // npx resolves a BIN NAME and falls through to the registry when nothing
    // local provides it. The bin is named after the package, so a miss lands on
    // this package -- but it can still fetch a different VERSION than `npm ci`
    // installed. CI must run exactly what it installed, so it uses the path
    // form, as this repo's own ci.yml does.
    const workflow = readFileSync(
      path.join(templates, 'workflows', 'guardrails.yml'),
      'utf8',
    );
    expect(workflow).toContain(
      'node ./node_modules/guardrails-core/dist/cli.mjs gate --mode=ci',
    );
    expect(workflow).toContain(
      'node ./node_modules/guardrails-core/dist/cli.mjs sanctions-check',
    );
    // Matched against the `run:` STEPS, not the file text: the template's own
    // comment names `npx guardrails-core` in order to explain why it is not used.
    expect(workflow).not.toMatch(/^ *- run: npx\b/m);
  });

  it('pins CI workflow actions to floating major tags, not a SHA', () => {
    // A pinned SHA written into a consumer's repository would rot silently
    // under THEIR Dependabot policy, unlike this repo's own workflows, which
    // pin because they control their own supply chain.
    const workflow = readFileSync(
      path.join(templates, 'workflows', 'guardrails.yml'),
      'utf8',
    );
    expect(workflow).toContain('actions/checkout@v6');
    expect(workflow).toContain('actions/setup-node@v6');
    expect(workflow).not.toMatch(/uses:\s*\S+@[0-9a-f]{40}/);
  });
});

/**
 * A checkout whose installed CLI is a stub exiting with `FAKE_EXIT`, so the
 * real pre-push hook can be run end to end without a gate behind it.
 */
function stubbedCheckout(): string {
  const checkout = mkdtempSync(path.join(tmpdir(), 'guardrails-push-hook-'));
  const cliDirectory = path.join(
    checkout,
    'node_modules',
    'guardrails-core',
    'dist',
  );
  mkdirSync(cliDirectory, { recursive: true });
  writeFileSync(
    path.join(cliDirectory, 'cli.mjs'),
    "process.exit(Number(process.env.FAKE_EXIT ?? '0'));\n",
  );
  return checkout;
}

function runPushHook(
  checkout: string,
  environment: Record<string, string>,
): ReturnType<typeof spawnSync> {
  return spawnSync('sh', [path.join(templates, 'githooks', 'pre-push')], {
    cwd: checkout,
    encoding: 'utf8',
    env: { ...process.env, ...environment },
  });
}

/**
Which locker this machine has -- the hook picks the same one.
*/
function locker(): 'lockf' | 'flock' | undefined {
  for (const tool of ['lockf', 'flock'] as const) {
    if (spawnSync('sh', ['-c', `command -v ${tool}`]).status === 0) {
      return tool;
    }
  }
  return undefined;
}

/**
Is `lock` held by someone else right now?
*/
function isHeld(tool: 'lockf' | 'flock', lock: string): boolean {
  const probe =
    tool === 'lockf'
      ? spawnSync('lockf', ['-k', '-s', '-t', '0', lock, 'true'])
      : spawnSync('flock', ['-n', lock, 'true']);
  return probe.status !== 0;
}

describe('the pre-push hook serializes the gate machine-wide', () => {
  it('runs the push gate under a lock named by GUARDRAILS_GATE_LOCK', () => {
    const hook = readFileSync(
      path.join(templates, 'githooks', 'pre-push'),
      'utf8',
    );
    expect(hook).toContain(
      'lock="${GUARDRAILS_GATE_LOCK:-$HOME/.guardrails-gate.lock}"',
    );
    expect(hook).toContain('ceiling="${GUARDRAILS_GATE_LOCK_TIMEOUT:-10800}"');
    expect(hook).toContain('gate --mode=push');
  });

  it('checks the install before it queues for the lock', () => {
    const hook = readFileSync(
      path.join(templates, 'githooks', 'pre-push'),
      'utf8',
    );
    expect(hook.indexOf('not installed')).toBeLessThan(hook.indexOf('lock="'));
  });

  it('says its lock-timeout in the words `guardrails ship` reads', () => {
    const hook = readFileSync(
      path.join(templates, 'githooks', 'pre-push'),
      'utf8',
    );
    expect(hook).toContain(LOCK_TIMEOUT_MARKER);
  });

  it('says an uninstalled checkout in the words `guardrails ship` reads', () => {
    const hook = readFileSync(
      path.join(templates, 'githooks', 'pre-push'),
      'utf8',
    );
    expect(hook).toContain(NOT_INSTALLED_MARKER);
  });

  it('passes a passing gate and blocks a failing one', () => {
    const checkout = stubbedCheckout();
    const lock = path.join(checkout, 'gate.lock');
    try {
      expect(
        runPushHook(checkout, { GUARDRAILS_GATE_LOCK: lock, FAKE_EXIT: '0' })
          .status,
      ).toBe(0);
      const blocked = runPushHook(checkout, {
        GUARDRAILS_GATE_LOCK: lock,
        FAKE_EXIT: '1',
      });
      expect(blocked.status).toBe(1);
      expect(blocked.stderr).toContain('guardrails: push blocked');
      expect(blocked.stderr).not.toContain(LOCK_TIMEOUT_MARKER);
    } finally {
      rmSync(checkout, { recursive: true, force: true });
    }
  });

  it('gives up on a held lock at the ceiling, and says so apart from a block', async () => {
    const tool = locker();
    const checkout = stubbedCheckout();
    const lock = path.join(checkout, 'gate.lock');
    const holdArguments =
      tool === 'lockf' ? ['-k', lock, 'sleep', '30'] : [lock, 'sleep', '30'];
    const holder = tool === undefined ? undefined : spawn(tool, holdArguments);
    try {
      if (tool === undefined) {
        // No locker on this machine: the hook must still run the gate.
        const result = runPushHook(checkout, { GUARDRAILS_GATE_LOCK: lock });
        expect(result.status).toBe(0);
        expect(result.stderr).toContain('running the gate unserialized');
        return;
      }
      const deadline = Date.now() + 5000;
      while (!isHeld(tool, lock) && Date.now() < deadline) {
        await new Promise((resolve) => setTimeout(resolve, 50));
      }
      const result = runPushHook(checkout, {
        GUARDRAILS_GATE_LOCK: lock,
        GUARDRAILS_GATE_LOCK_TIMEOUT: '1',
      });
      expect(result.status).toBe(1);
      expect(result.stderr).toContain('waiting for the lock (up to 1s)');
      expect(result.stderr).toContain(LOCK_TIMEOUT_MARKER);
      expect(result.stderr).not.toContain('guardrails: push blocked');
    } finally {
      holder?.kill('SIGKILL');
      rmSync(checkout, { recursive: true, force: true });
    }
  });
});
